import{U as e,gt as t,nt as n,rt as r}from"./chunks/framework.B3obAz7o.js";var i=JSON.parse(`{"title":"ADR 0001: Canonical internal boundaries","description":"","frontmatter":{},"headers":[],"relativePath":"decisions/0001-canonical-internal-boundaries.md","filePath":"decisions/0001-canonical-internal-boundaries.md","lastUpdated":1785311946000}`),a={name:`decisions/0001-canonical-internal-boundaries.md`};function o(e,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[r(`<h1 id="adr-0001-canonical-internal-boundaries" tabindex="-1">ADR 0001: Canonical internal boundaries <a class="header-anchor" href="#adr-0001-canonical-internal-boundaries" aria-label="Permalink to “ADR 0001: Canonical internal boundaries”">​</a></h1><ul><li>Status: Accepted</li><li>Date: 2026-07-29</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>The same behavior had accumulated in several public-surface adapters: Node and WASM optimized assets with similar policy code, multiple format crates wrote sfnt directories, native release scripts repeated platform maps, and the Rust CLI build command owned orchestration, cache persistence, locking, and output safety in one file.</p><p>Those repetitions made local edits risky. A new native target, output-safety rule, diagnostic behavior, or sfnt invariant could be updated in one path while another path silently drifted.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>Use one canonical module for each cross-cutting invariant and keep public facades thin:</p><table tabindex="0"><thead><tr><th>Invariant</th><th>Canonical owner</th></tr></thead><tbody><tr><td>Node workspace reads, path expansion, safe cleanup, and writes</td><td><code>packages/fontmin/src/workspace-io.ts</code></td></tr><tr><td>Node/WASM optimizer policy and diagnostic normalization</td><td><code>packages/fontmin/src/runtime-neutral/</code></td></tr><tr><td>Rust CLI cache persistence and locking</td><td><code>apps/fontmin/src/commands/build/cache.rs</code></td></tr><tr><td>Rust CLI output containment and guarded cleanup</td><td><code>apps/fontmin/src/commands/build/output.rs</code></td></tr><tr><td>sfnt directory validation and serialization</td><td><code>crates/fontmin_ttf/src/sfnt.rs</code></td></tr><tr><td>Native target-to-package layout</td><td><code>scripts/native-release-layout.mjs</code></td></tr><tr><td>CLI integration-test process and temporary workspace setup</td><td><code>apps/fontmin/tests/cli/support.rs</code></td></tr></tbody></table><p>SVG icon-font internals are separated by responsibility into markup extraction, path geometry, and TTF table construction. Their public functions remain in <code>crates/fontmin_svg/src/icon.rs</code>.</p><p>The N-API <code>targets</code> array is the authoritative native target inventory. Platform package names, directories, artifact names, runtime selection, and metadata checks are derived from it. Workflow matrices remain declarative YAML, with tests preventing drift from the inventory.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>A cross-runtime policy change has one implementation and must pass both Node and WASM tests.</li><li>A format crate cannot customize sfnt directory mechanics; it supplies table data to the canonical writer.</li><li>Cache and output safety can evolve independently of CLI build orchestration.</li><li>Adding a native target requires the N-API target, platform manifest, and workflow runner, while validation reports every inconsistent surface.</li><li>Internal modules may be private and opinionated. Public API compatibility is still governed by <code>contracts/</code> and the deprecation policy.</li></ul><p>The trade-off is additional internal modules and dependencies on their interfaces. <code>CONTEXT.md</code> files record ownership so new behavior deepens an existing module instead of recreating a parallel implementation.</p><h2 id="rejected-alternatives" tabindex="-1">Rejected alternatives <a class="header-anchor" href="#rejected-alternatives" aria-label="Permalink to “Rejected alternatives”">​</a></h2><ul><li>Keep duplicated implementations synchronized by convention. Tests showed that several independent lists and serializers were already costly to audit.</li><li>Create a general utility crate or package for all shared code. The concerns have different dependencies and rates of change; one broad utility module would weaken locality.</li><li>Generate CI workflow YAML from code. The repository keeps reviewable workflow configuration and uses a drift test instead of adding a generation step.</li></ul>`,15)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};